CREATE UNIQUE INDEX idx_inv_item ON product_inventory(order_item_id, id) WHERE order_item_id IS NOT NULL;
CREATE TABLE coupons ( id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, type TEXT NOT NULL CHECK (type IN ('percent','fixed')), value INTEGER NOT NULL CHECK (value > 0), min_order INTEGER NOT NULL DEFAULT 0, max_discount INTEGER, max_uses INTEGER, used_count INTEGER NOT NULL DEFAULT 0, per_user_limit INTEGER NOT NULL DEFAULT 1, starts_at TEXT, expires_at TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK (type <> 'percent' OR value <= 100), CHECK (max_uses IS NULL OR used_count <= max_uses) );
CREATE TABLE homepage_banners ( id TEXT PRIMARY KEY, title TEXT NOT NULL, subtitle TEXT, image_key TEXT, cta_label TEXT, cta_url TEXT, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)) );
CREATE TABLE wallet_accounts ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, balance INTEGER NOT NULL DEFAULT 0 CHECK (balance >= 0), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE TABLE wallet_transactions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK (kind IN ('deposit','purchase','refund','adjustment')), amount INTEGER NOT NULL CHECK (amount <> 0), balance_after INTEGER NOT NULL CHECK (balance_after >= 0), reference_type TEXT NOT NULL, reference_id TEXT NOT NULL, note TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (reference_type, reference_id, kind) );
CREATE INDEX idx_wtx_user ON wallet_transactions(user_id, created_at);
CREATE TABLE payment_methods ( code TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL CHECK (type IN ('manual','gateway')), enabled INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0,1)), account_title TEXT NOT NULL DEFAULT '', account_number TEXT NOT NULL DEFAULT '', instructions TEXT NOT NULL DEFAULT '', min_amount INTEGER NOT NULL DEFAULT 10000, max_amount INTEGER NOT NULL DEFAULT 50000000, sort_order INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE deposits ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), method_code TEXT NOT NULL REFERENCES payment_methods(code), amount INTEGER NOT NULL CHECK (amount > 0), payment_reference TEXT, sender_name TEXT, sender_account TEXT, proof_key TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), reviewed_by TEXT REFERENCES users(id), review_note TEXT, reviewed_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_dep_user ON deposits(user_id, created_at);
CREATE INDEX idx_dep_status ON deposits(status, created_at);
CREATE UNIQUE INDEX idx_dep_ref ON deposits(method_code, payment_reference) WHERE payment_reference IS NOT NULL;
CREATE TABLE payment_events ( id TEXT PRIMARY KEY, provider TEXT NOT NULL, event_id TEXT NOT NULL, payload TEXT NOT NULL, signature_valid INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'received', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE (provider, event_id) );
CREATE TABLE orders ( id TEXT PRIMARY KEY, order_no TEXT NOT NULL UNIQUE, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','completed','cancelled','refunded','failed')), subtotal INTEGER NOT NULL CHECK (subtotal >= 0), discount INTEGER NOT NULL DEFAULT 0 CHECK (discount >= 0), total INTEGER NOT NULL CHECK (total >= 0), coupon_id TEXT REFERENCES coupons(id), coupon_code TEXT, idempotency_key TEXT NOT NULL, customer_note TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), completed_at TEXT, UNIQUE (user_id, idempotency_key) );
CREATE INDEX idx_orders_user ON orders(user_id, created_at);
CREATE INDEX idx_orders_status ON orders(status, created_at);
CREATE TABLE order_items ( id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), plan_id TEXT NOT NULL REFERENCES product_plans(id), product_name TEXT NOT NULL, plan_name TEXT NOT NULL, unit_price INTEGER NOT NULL CHECK (unit_price > 0), discount INTEGER NOT NULL DEFAULT 0 CHECK (discount >= 0), paid INTEGER NOT NULL CHECK (paid >= 0), delivery_type TEXT NOT NULL CHECK (delivery_type IN ('automatic','manual','api')), refund_eligible INTEGER NOT NULL DEFAULT 0, customer_input TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','completed','failed','cancelled','refunded')), provider_ref TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), completed_at TEXT );
CREATE INDEX idx_oi_order ON order_items(order_id);
CREATE INDEX idx_oi_plan ON order_items(plan_id);
CREATE INDEX idx_oi_status ON order_items(status, delivery_type);
CREATE TABLE order_deliveries ( id TEXT PRIMARY KEY, order_item_id TEXT NOT NULL REFERENCES order_items(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('credential','text','file')), content_enc TEXT, file_key TEXT, file_name TEXT, note TEXT, delivered_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_od_item ON order_deliveries(order_item_id);
CREATE TABLE order_events ( id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, order_item_id TEXT, kind TEXT NOT NULL, message TEXT NOT NULL, actor_id TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_oe_order ON order_events(order_id, created_at);
CREATE TABLE coupon_redemptions ( id TEXT PRIMARY KEY, coupon_id TEXT NOT NULL REFERENCES coupons(id), user_id TEXT NOT NULL REFERENCES users(id), order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), amount INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) );
CREATE INDEX idx_cr_coupon_user ON coupon_redemptions(coupon_id, user_id);
